CREATE FUNCTION public.foundation_update_profile(new_name text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN IF auth.uid() IS NULL OR length(btrim(new_name))=0 OR length(new_name)>200 THEN RAISE EXCEPTION 'Invalid profile'; END IF; UPDATE public.org_members SET full_name=btrim(new_name) WHERE user_id=auth.uid() AND active AND foundation_role IS NOT NULL; IF NOT FOUND THEN RAISE EXCEPTION 'No staff membership'; END IF; END $$;
REVOKE ALL ON FUNCTION public.foundation_update_profile(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.foundation_update_profile(text) TO authenticated;
CREATE OR REPLACE FUNCTION private.foundation_client_validate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE seq text; BEGIN IF TG_OP='INSERT' THEN seq:=nextval('public.crm_client_number_seq')::text; NEW.number := 'K-'||lpad(seq,greatest(4,length(seq)),'0'); ELSE IF NEW.number<>OLD.number OR NEW.organization_id<>OLD.organization_id OR NEW.type<>OLD.type THEN RAISE EXCEPTION 'Immutable client identity'; END IF; END IF; IF NEW.type='person' AND (btrim(NEW.first_name)='' OR btrim(NEW.last_name)='') THEN RAISE EXCEPTION 'Person name required'; END IF; IF NEW.type='company' AND btrim(NEW.company_name)='' THEN RAISE EXCEPTION 'Company name required'; END IF; IF NEW.type='household' AND btrim(NEW.household_name)='' THEN RAISE EXCEPTION 'Household name required'; END IF; IF NEW.contact_person_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.crm_clients WHERE id=NEW.contact_person_id AND organization_id=NEW.organization_id AND type='person') THEN RAISE EXCEPTION 'Invalid contact person'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION private.foundation_dossier_validate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE seq integer; yr integer; BEGIN IF TG_OP='INSERT' THEN yr:=extract(year FROM CURRENT_DATE); INSERT INTO public.crm_number_counters(service,year,value) VALUES(NEW.service,yr,1) ON CONFLICT(service,year) DO UPDATE SET value=public.crm_number_counters.value+1 RETURNING value INTO seq; NEW.number:=NEW.service||'-'||yr||'-'||lpad(seq::text,greatest(4,length(seq::text)),'0'); ELSE IF NEW.number<>OLD.number OR NEW.service<>OLD.service OR NEW.client_id<>OLD.client_id OR NEW.organization_id<>OLD.organization_id THEN RAISE EXCEPTION 'Immutable dossier identity'; END IF; END IF; IF NEW.responsible_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.org_members WHERE organization_id=NEW.organization_id AND user_id=NEW.responsible_id AND active AND foundation_role IS NOT NULL) THEN RAISE EXCEPTION 'Invalid responsible member'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;